source_label":"足够","source_level_label":"5","pinyin":"zúgòu","pinyin_plain":"zugou","part_of_speech":"动","meaning_es":"suficiente; bastante"},{"source_order":3590,"hanzi":"组成","source_label":"组成","source_level_label":"5","pinyin":"zǔchéng","pinyin_plain":"zucheng","part_of_speech":"动","meaning_es":"formar; componer; constituir"},{"source_order":3591,"hanzi":"组合","source_label":"组合","source_level_label":"5","pinyin":"zǔhé","pinyin_plain":"zuhe","part_of_speech":"动、名","meaning_es":"ensamblar; combinar; componer; combinación; asociación; conjunto; compilación; (matemáticas) combinatorio"},{"source_order":3592,"hanzi":"阻止","source_label":"阻止","source_level_label":"5","pinyin":"zǔzhǐ","pinyin_plain":"zuzhi","part_of_speech":"动","meaning_es":"prevenir; bloquear"},{"source_order":3593,"hanzi":"组织","source_label":"组织","source_level_label":"5","pinyin":"zǔzhī","pinyin_plain":"zuzhi","part_of_speech":"动、名","meaning_es":"organizar; organización; (biología) tejido; (textiles) ligamento"},{"source_order":3594,"hanzi":"嘴巴","source_label":"嘴巴","source_level_label":"5","pinyin":"zuǐba","pinyin_plain":"zuiba","part_of_speech":"名","meaning_es":"boca; bofetada en la cara"},{"source_order":3595,"hanzi":"醉","source_label":"醉","source_level_label":"5","pinyin":"zuì","pinyin_plain":"zui","part_of_speech":"动","meaning_es":"ebrio; embriagado"},{"source_order":3596,"hanzi":"最初","source_label":"最初","source_level_label":"5","pinyin":"zuìchū","pinyin_plain":"zuichu","part_of_speech":"名","meaning_es":"primero; primario; inicial; original; al principio; inicialmente; originalmente"},{"source_order":3597,"hanzi":"最佳","source_label":"最佳","source_level_label":"5","pinyin":"zuìjiā","pinyin_plain":"zuijia","part_of_speech":"形","meaning_es":"óptimo; ideal; máximo; el mejor (atleta, película, etc.)"},{"source_order":3598,"hanzi":"尊敬","source_label":"尊敬","source_level_label":"5","pinyin":"zūnjìng","pinyin_plain":"zunjing","part_of_speech":"动、形","meaning_es":"respetar; reverenciar; estimar; honorable; distinguido (usado en ocasiones formales antes de un tratamiento)"},{"source_order":3599,"hanzi":"遵守","source_label":"遵守","source_level_label":"5","pinyin":"zūnshǒu","pinyin_plain":"zunshou","part_of_speech":"动","meaning_es":"acatar; atenerse a; respetar (un acuerdo)"},{"source_order":3600,"hanzi":"作出","source_label":"作出","source_level_label":"5","pinyin":"zuòchū","pinyin_plain":"zuochu","part_of_speech":"动","meaning_es":"sacar; proponer; hacer (una elección, decisión, propuesta, respuesta, comentario, etc.); emitir (un permiso…"}]$catalog$::jsonb) as entry (
  source_order integer,
  hanzi text,
  source_label text,
  source_level_label text,
  pinyin text,
  pinyin_plain text,
  part_of_speech text,
  meaning_es text
);

insert into words (hanzi, hsk_level, hsk_version, origin, status)
select distinct hanzi, 5, '3.0', 'open_data'::content_origin, 'unreviewed'::review_status
from hsk_source_entries_temp
on conflict (hanzi) do nothing;

-- Reutiliza únicamente un sentido previo sin catálogo y todavía sin revisar.
-- Si el sentido fue curado, crea otro borrador en vez de apropiárselo.
with matched_entries as (
  select
    words.id as word_id,
    source_entries.*,
    count(*) over (partition by words.id, source_entries.pinyin) as matching_entry_count
  from hsk_source_entries_temp as source_entries
  join words using (hanzi)
), reusable as (
  select matched_entries.*, matched_sense.id as sense_id
  from matched_entries
  left join lateral (
    select senses.id
    from senses
    where senses.word_id = matched_entries.word_id
      and senses.pinyin = matched_entries.pinyin
      and senses.catalog_source_id is null
      and senses.status = 'unreviewed'
    order by senses.position
    limit 1
  ) as matched_sense on true
  where matched_entries.matching_entry_count = 1
)
update senses
set
  catalog_source_id = 'cti-hsk3-2026',
  catalog_source_order = reusable.source_order,
  pinyin_plain = coalesce(senses.pinyin_plain, reusable.pinyin_plain),
  category = coalesce(senses.category, reusable.part_of_speech),
  meaning_es = coalesce(senses.meaning_es, reusable.meaning_es)
from reusable
where senses.id = reusable.sense_id
  and reusable.sense_id is not null
  and senses.status = 'unreviewed';

with candidates as (
  select words.id as word_id, source_entries.*
  from hsk_source_entries_temp as source_entries
  join words using (hanzi)
  where not exists (
    select 1 from senses
    where senses.catalog_source_id = 'cti-hsk3-2026'
      and senses.catalog_source_order = source_entries.source_order
  )
), positioned as (
  select candidates.*,
    coalesce((select max(senses.position) from senses where senses.word_id = candidates.word_id), 0)
      + row_number() over (partition by candidates.word_id order by candidates.source_order) as position
  from candidates
)
insert into senses (
  word_id, position, pinyin, pinyin_plain, category, meaning_es,
  catalog_source_id, catalog_source_order, origin, status
)
select
  word_id, position, pinyin, pinyin_plain, part_of_speech, meaning_es,
  'cti-hsk3-2026', source_order, 'open_data'::content_origin, 'unreviewed'::review_status
from positioned
on conflict (word_id, position) do nothing;

insert into word_levels (
  word_id, sense_id, standard, level, source_id, source_order,
  source_label, source_level_label, pinyin, part_of_speech
)
select
  words.id, matched_sense.id, 'hsk-3.0', 5, 'cti-hsk3-2026',
  source_entries.source_order, source_entries.source_label,
  source_entries.source_level_label, source_entries.pinyin,
  source_entries.part_of_speech
from hsk_source_entries_temp as source_entries
join words using (hanzi)
left join lateral (
  select senses.id
  from senses
  where senses.catalog_source_id = 'cti-hsk3-2026'
    and senses.catalog_source_order = source_entries.source_order
  order by senses.position
  limit 1
) as matched_sense on true
on conflict (standard, source_order) do nothing;

drop table hsk_source_entries_temp;
